<?php defined('BASEPATH') OR exit('No direct script access allowed');class App_builder extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('App_builder_model','ab');}function dashboard(){return $this->respond($this->ab->rollup($this->c['organizationId']));}function agents(){return $this->respond(array(array('group'=>'Product','agents'=>array('PM','Business Analyst','Solution Architect')),array('group'=>'Design','agents'=>array('UX Researcher','UI Designer')),array('group'=>'Engineer','agents'=>array('Frontend Engineer','Backend Engineer','Mobile Engineer','Desktop Engineer','Database Engineer','AI Engineer')),array('group'=>'Quality','agents'=>array('QA Engineer','Security Engineer')),array('group'=>'Platform','agents'=>array('DevOps Engineer','Site Reliability Engineer')),array('group'=>'Delivery','agents'=>array('Technical Writer','Release Manager'))));}function projects($id=NULL){$m=$this->input->method(TRUE);$o=$this->c['organizationId'];if($m==='GET'){if($id){$r=$this->ab->one('projects',$o,$id);return$r?$this->respond($r):$this->fail('NOT_FOUND','Project not found',404);}$rows=$this->ab->list_rows('projects',$o);$q=mb_strtolower((string)$this->input->get('q'));$target=$this->input->get('targetType');$rows=array_values(array_filter($rows,function($r)use($q,$target){return(!$target||$r['targetType']===$target)&&(!$q||mb_strpos(mb_strtolower($r['name'].' '.($r['description']??'')),$q)!==FALSE);}));return$this->respond($rows);}if($m==='DELETE')return$this->ab->remove_project($o,$id)?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Project not found',404);$d=$this->body();if(!$id&&(!isset($d['name'],$d['systemPrompt'])||trim($d['name'])===''||trim($d['systemPrompt'])===''))return$this->fail('VALIDATION_ERROR','name and systemPrompt required',422);if(isset($d['name'])&&(strlen($d['name'])>140||trim($d['name'])==='')||isset($d['systemPrompt'])&&(strlen($d['systemPrompt'])>20000||trim($d['systemPrompt'])==='')||isset($d['targetType'])&&!in_array($d['targetType'],array('WEB','DESKTOP','MOBILE','API','MICROSERVICE','BROWSER_EXTENSION','CLI'),TRUE)||isset($d['techStack'])&&!is_array($d['techStack']))return$this->fail('VALIDATION_ERROR','Invalid project input',422);$r=$this->ab->project_save($o,$id,$this->c['sub'],$d);return$r?$this->respond($r,$id?200:201):$this->fail('NOT_FOUND','Project not found',404);}function project_children($id,$kind){$o=$this->c['organizationId'];if($this->input->method(TRUE)==='GET'){$f=array('project_id'=>$id);if($kind==='tasks'&&$this->input->get('completed')!==NULL)$f['is_completed']=$this->input->get('completed')==='true'?1:0;if($kind==='runs'&&$this->input->get('status')!==NULL)$f['status']=$this->input->get('status');return$this->respond($this->ab->list_rows($kind,$o,$f));}$d=$this->body();if($kind==='tasks'){if(!$this->valid_task($d,TRUE))return;$r=$this->ab->task_save($o,$id,NULL,$d);return$r?$this->respond($r,201):$this->fail('NOT_FOUND','Project not found',404);}$version=$d['version']??'v1.0.0';if(!preg_match('/^v\d+\.\d+\.\d+$/',$version))return$this->fail('VALIDATION_ERROR','Version must use vMAJOR.MINOR.PATCH',422);list($r,$e)=$this->ab->create_run($o,$id,$this->c['sub'],$version);return$e?$this->fail($e,'Build version already exists',409):($r?$this->respond($r,201):$this->fail('NOT_FOUND','Project not found',404));}function tasks($id){$m=$this->input->method(TRUE);if($m==='GET'){$r=$this->ab->one('tasks',$this->c['organizationId'],$id);return$r?$this->respond($r):$this->fail('NOT_FOUND','Task not found',404);}if($m==='DELETE')return$this->ab->remove('tasks',$this->c['organizationId'],$id)?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Task not found',404);$d=$this->body();if(!$this->valid_task($d,FALSE))return;$r=$this->ab->task_save($this->c['organizationId'],NULL,$id,$d);return$r?$this->respond($r):$this->fail('NOT_FOUND','Task not found',404);}function generate($id){$t=$this->ab->one('tasks',$this->c['organizationId'],$id);if(!$t)return$this->fail('NOT_FOUND','Task not found',404);$this->load->library('Ai_provider');$p=$this->ab->one('projects',$this->c['organizationId'],$t['projectId']);$res=$this->ai_provider->complete(array(array('role'=>'system','content'=>'Write production-quality code. Return only code.'),array('role'=>'user','content'=>'Project: '.($p['name']??'').' Task: '.$t['title'].' '.($t['description']??''))));if(!$res['ok'])return$this->respond(array('task'=>$t,'modelSource'=>'echo-demo'));$t=$this->ab->generate($this->c['organizationId'],$id,trim($res['content']),'real');return$this->respond(array('task'=>$t,'modelSource'=>'real'));}function build($id,$action=NULL){if(!$action){$r=$this->ab->one('runs',$this->c['organizationId'],$id);return$r?$this->respond($r):$this->fail('NOT_FOUND','Build not found',404);}if($action==='advance')$r=$this->ab->advance($this->c['organizationId'],$id,$this->c['sub']);else list($r,$e)=$this->ab->retry($this->c['organizationId'],$id,$this->c['sub']);return!empty($e)?$this->fail($e,'Build cannot be retried',409):($r?$this->respond($r,$action==='retry'?201:200):$this->fail('NOT_FOUND','Build not found',404));}function artifacts($id=NULL,$action=NULL){$o=$this->c['organizationId'];if(!$id){$f=array();if($this->input->get('projectId')!==NULL)$f['project_id']=$this->input->get('projectId');if($this->input->get('published')!==NULL)$f['published']=$this->input->get('published')==='true'?1:0;return$this->respond($this->ab->list_rows('artifacts',$o,$f));}if(!$action){$r=$this->ab->one('artifacts',$o,$id);return$r?$this->respond($r):$this->fail('NOT_FOUND','Artifact not found',404);}list($r,$e)=$action==='request-release'?$this->ab->request_release($o,$id,$this->c['sub']):$this->ab->release($o,$id);return$e?$this->fail($e,'Artifact release gate rejected the action',409):($r?$this->respond($r,$action==='request-release'?201:200):$this->fail('NOT_FOUND','Artifact not found',404));}function approvals($id=NULL){$o=$this->c['organizationId'];if(!$id)return$this->respond($this->ab->list_rows('approvals',$o,$this->input->get('status')?array('status'=>$this->input->get('status')):array()));$d=$this->body();if(!isset($d['approved'],$d['decidedBy']))return$this->fail('VALIDATION_ERROR','approved and decidedBy required',422);list($r,$e)=$this->ab->decide($o,$id,$d);return$e?$this->fail($e,'Approval already decided',409):($r?$this->respond($r):$this->fail('NOT_FOUND','Approval not found',404));}private function valid_task($d,$create){$agents=array('PM','Business Analyst','Solution Architect','UX Researcher','UI Designer','Frontend Engineer','Backend Engineer','Mobile Engineer','Desktop Engineer','Database Engineer','AI Engineer','QA Engineer','Security Engineer','DevOps Engineer','Site Reliability Engineer','Technical Writer','Release Manager');if($create&&(!isset($d['assignedAgent'],$d['title']))||isset($d['assignedAgent'])&&!in_array($d['assignedAgent'],$agents,TRUE)||isset($d['title'])&&(trim($d['title'])===''||strlen($d['title'])>200)||isset($d['description'])&&$d['description']!==NULL&&strlen($d['description'])>5000||isset($d['outputCode'])&&$d['outputCode']!==NULL&&strlen($d['outputCode'])>50000){$this->fail('VALIDATION_ERROR','Invalid task input',422);return FALSE;}return TRUE;}}
